  'Cancel move': 'Áthelyezés megszakítása',
  'Cancel copy': 'Másolás megszakítása',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Helyezze át a teljes mentett beszélgetést, ellenőrzőlistát, mellékleteket és fájlokat. A szolgáltatói munkamenetek és hitelesítő adatok ezen a számítógépen maradnak. A célgépen lévő szál az ottani alapértelmezett harness-t használja, és legfeljebb annyi hozzáféréssel rendelkezik, mint ez a szál. Semmi sem fut, amíg ott el nem küldi a következő üzenetét. A megnyitás után módosíthatja a modellt. Ez a szál helyreállítás céljából itt marad, csak olvashatóként.',
