  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Állítsd be a CuaDrivert ezen a futtatókörnyezeti gazdagépen. Az operációs rendszer engedélyeit a CuaDriver kezeli; a Dovo MCP-n keresztül kapcsolja össze az ügynököket.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Gazdagépen futó programok nevei vagy elérési útjai, shell-idézőjelek nélkül. Az ügynöki felülírások elsőbbséget élveznek. Az új terminálok ezeket a shellbeállításokat használják.',
  'Loading {value0} settings…': '{value0} beállításainak betöltése…',
