    'Automatikus shell: {value0}. Alapértelmezés: -l (bejelentkezési shell).',
  'Enable agent computer use on this computer':
    'Ügynöki számítógép-használat engedélyezése ezen a számítógépen',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Az írható ügynökök hozzáférést kapnak a számítógép asztalához. Az írásvédett ügynökök ki vannak zárva. A felhasználó és az ügynökök közösen használják az asztalt és az alkalmazások állapotát.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Hagyd üresen a Cua Driver mezőt, hogy a rendszer megkeresse ezen a számítógépen a PATH változóban vagy a szokásos telepítési mappában. A módosítások az új ügynöki körökre érvényesek.',
  '1. Install on this computer': '1. Telepítés erre a számítógépre',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Futtasd a hivatalos telepítőt a futtatókörnyezeti gazdagépen, majd frissítsd az állapotot. Letölti és telepíti a CuaDrivert; nincs szükség Cua-fiókra.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'A minimális Linux-rendszerekhez libxi6 és at-spi2-core szükséges. A GNOME-hoz kell a Cua mellékelt WinRects segédprogramja; lásd a telepítési útmutatót.',
  'Install and set up Cua Driver': 'Cua Driver telepítése és beállítása',
  'Detect / check Cua Driver': 'Cua Driver keresése / ellenőrzése',
  '2. Permissions & desktop access': '2. Engedélyek és asztalhozzáférés',
  '3. Agent MCP, skills & hooks': '3. Ügynök MCP, készségek és hookok',
  '4. Computer History (optional preview)': '4. Számítógépes előzmények (nem kötelező előnézet)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Add meg a CuaDrivernek a Kisegítő lehetőségek és a Képernyőfelvétel engedélyt macOS-en, majd fogadd el az újraindítást. Az asztalhozzáférés tesztelése felsorolja az alkalmazásokat, de nem módosítja őket. A démon vezérlői az aktív számítógép-használati munkamenetekre vannak hatással.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Mentsd a számítógép-használat kapcsolóját, hogy az automatikus dovo_cua MCP bekapcsoljon az új, írható ügynöki körökben. Nincs szükség kézi MCP-regisztrációra. Telepítsd a hivatalos, nem kötelező skill-csomagot; telepítéskor összekapcsolja az ezen a számítógépen észlelt ügynököket.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Bekapcsolása önkéntes, és titkosított, csak metaadatokat tartalmazó előzményeket hoz létre. Engedélyezése újraindíthatja a démont. Letiltása megőrzi a rögzített adatokat; a szüneteltetés ideiglenesen leállítja a rögzítést. Nem támogatott verzió esetén hiba jelenik meg. Az adatok a futtatókörnyezeti gazdagépen maradnak; a Legutóbbi előzmények megtekintése legfeljebb 20 eseményt tölt be ide.',
  'Delete recorded Computer History?': 'Törlöd a rögzített számítógépes előzményeket?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Törli az összes rögzített előzményt és a titkosítási kulcsát ezen a számítógépen. Ez nem vonható vissza.',
