  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Minden új beszélgetés ügynökét, annak parancsait és termináljait egy helyi Docker- vagy Podman-konténerben futtatja. Csak a munkapéldány és a kiválasztott ügynök bejelentkezése csatolódik. A futó beszélgetések megtartják a beállításukat.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Hálózati hozzáférés nélkül az ügynök nem éri el a modellje API-ját, kivéve ha az az API a homokozóban fut. A csomagtelepítések és a webes kérések szintén sikertelenek.',
