  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Az ügynök, a parancsai és a termináljai egy konténerben futnak. Csak ez a munkapéldány és az ügynök bejelentkezése csatolódik.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Visszatartja az Ön üzenete nélkül futó új munkát, amikor annak becsült költsége eléri a korlátot. Ez vonatkozik a botok további lépéseire, egy bot rutinlépéseire, az ütemezett üzenetekre és az alügynökökre. Minden szál vagy bot az alügynökeivel együtt számít. A bot nélküli rutin minden futtatáskor új számlálást kezd. Saját korlátait a Figyelés és korlátok részben állítsa be. A következő üzenete vagy a Folytatás nullázza a számlálást. Az ár nélküli körök szintén visszatartják a munkát. A futó kör mindig befejeződik.',
